# -*- coding: utf-8 -*-
"""Prosopography: persons, offices, collectives and institutions as attested in the provided
documents. Every statement carries its source. Name variants are recorded as written.
scope: 'hunt' (Alaska mammoth affair, 1906–1930), 'prologue' (Adams mammoth / refrigeration
sections of the Tale), 'research' (people active in 2019 research), 'office' (unnamed office-holder).
'pi_characterisation' quotes the PI's Cast of Characters verbatim where one exists (the Cast is her
working notes, unpublished, 2019; the build verifies every line against the Cast text).
'characterisations' = [(text, source)]: evaluative phrases from the provided texts, kept apart from
'roles', which lists offices and functions only. Both are rendered in the writer's voice, never as fact.
'institutions' = [aff(id, status, evidence, ...)]: status 'stated' only where a provided text names
the person in that institution (the quotation is verified at build time); 'inferred' where the
affiliation is the model's reading of context (drawn dashed, listed separately). evidence_kind
'letterhead' marks a printed officer list rather than a sentence written by the signer."""

def aff(inst, status, evidence=None, note=None, evidence_kind=None):
    """Person–institution affiliation with its own evidence (one quotation, verified at build)."""
    d = dict(id=inst, status=status)
    if evidence is not None: d['evidence'] = evidence
    if note: d['note'] = note
    if evidence_kind: d['evidence_kind'] = evidence_kind
    return d

